div.script:
// Canvas Ember Effect
const canvas = document.getElementById('ember-canvas');
if (canvas) {
  const ctx = canvas.getContext('2d');
  let width = canvas.width = window.innerWidth;
  let height = canvas.height = window.innerHeight;

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const embers = [];
  for (let i = 0; i < 45; i++) {
    embers.push({
      x: Math.random() * width,
      y: Math.random() * height + height,
      radius: Math.random() * 2.5 + 0.5,
      color: Math.random() > 0.4 ? '#f97316' : '#ef4444',
      vy: Math.random() * -1.5 - 0.5,
      vx: (Math.random() - 0.5) * 0.8,
      alpha: Math.random() * 0.8 + 0.2
    });
  }

  function animate() {
    ctx.clearRect(0, 0, width, height);
    embers.forEach(e => {
      e.y += e.vy;
      e.x += e.vx;
      if (e.y < -10) {
        e.y = height + 10;
        e.x = Math.random() * width;
      }
      ctx.beginPath();
      ctx.arc(e.x, e.y, e.radius, 0, Math.PI * 2);
      ctx.fillStyle = e.color;
      ctx.globalAlpha = e.alpha;
      ctx.shadowBlur = 8;
      ctx.shadowColor = e.color;
      ctx.fill();
    });
    requestAnimationFrame(animate);
  }
  animate();
}

// Audio & Launch Script
function playLaunchSound() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(220, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.3);
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.3);
  } catch(e) {}
}

document.getElementById('launch-btn').onclick = async function() {
  playLaunchSound();
  try {
    const rawUrl = "https://raw.githubusercontent.com/Mistyitz/PyrosChatSite/main/index.html";
    const response = await fetch(rawUrl);

    if (!response.ok) throw new Error("Could not load index.html");
    const htmlCode = await response.text();

    const win = window.open('about:blank', '_blank');
    if (win) {
      win.document.open();
      win.document.write(htmlCode);
      win.document.close();
    } else {
      alert("Popup blocked! Please allow popups to launch Pyro's Chat Hub.");
    }
  } catch (err) {
    alert("Failed to fetch application code from GitHub.");
  }
};
